/** One list, rendered with its nested lists inside their parent item. */
function renderList(items, definitions) {
  function renderItem(item) {
    const text = renderInline(item.text, definitions)
    if (item.children.length === 0) {
      return `<li>${text}</li>`
    } else {
      const childrenHtml = renderItems(item.children)
      return `<li>${text}\n${childrenHtml}\n</li>`
    }
  }

  function renderItems(itemList) {
    const renderedItems = itemList.map(renderItem)
    return `<ul>\n${renderedItems.join('\n')}\n</ul>`
  }

  return renderItems(items)
}

